import{_ as e,b as i,c as s,I as o}from"./chunks/framework.C6cPs9Ia.js";const u=JSON.parse('{"title":"博客的三次搬家","description":"柳卿烟博客的三次搬家记录——从手写静态页到 VitePress 的完整折腾过程","frontmatter":{"title":"博客的三次搬家","date":"2026-09-15T00:00:00.000Z","tags":["建站","折腾","日常"],"pinned":true,"cover":"/LQY/images/moment-3.jpg","head":[["meta",{"name":"description","content":"柳卿烟博客的三次搬家记录——从手写静态页到 VitePress 的完整折腾过程"}],["meta",{"name":"keywords","content":"建站, 博客, VitePress, 折腾记录"}]]},"headers":[],"relativePath":"posts/theme-migration.md","filePath":"posts/theme-migration.md"}'),r={name:"posts/theme-migration.md"};function a(n,t,l,c,p,d){return i(),s("div",null,[...t[0]||(t[0]=[o('<p>这个博客已经是第三代了。趁刚搬完家，把三次的经历整理一下，也算是给未来的自己留个记录。</p><hr><h2 id="一代目-手写静态页" tabindex="-1">一代目：手写静态页 <a class="header-anchor" href="#一代目-手写静态页" aria-label="Permalink to &quot;一代目：手写静态页&quot;">​</a></h2><p>最早的版本是纯 HTML + CSS 手写的，一个页面一个文件，改个导航要动五个文件。</p><p>现在回头看确实简陋，但那种&quot;每个像素都是自己挪的&quot;的成就感，后来用什么主题都找不回来。代码写得丑，不过里面放的内容都是认真的。</p><h2 id="二代目-astro-mizuki" tabindex="-1">二代目：Astro + Mizuki <a class="header-anchor" href="#二代目-astro-mizuki" aria-label="Permalink to &quot;二代目：Astro + Mizuki&quot;">​</a></h2><p>后来换成了 Astro 的 Mizuki 主题。粉粉的，功能也全：搜索、评论、RSS、暗色模式都有，用了挺长时间。</p><p>换掉它的理由说出来有点任性——我就是想要个蓝色的站点。颜色这种东西，看久了真的会腻。</p><h2 id="三代目-vitepress-魔改主题-现在" tabindex="-1">三代目：VitePress 魔改主题（现在） <a class="header-anchor" href="#三代目-vitepress-魔改主题-现在" aria-label="Permalink to &quot;三代目：VitePress 魔改主题（现在）&quot;">​</a></h2><p>就是你现在看到的这个。</p><div class="tip custom-block"><p class="custom-block-title">三代目技术清单</p><ul><li><strong>框架</strong>：VitePress 1.6 + Vue 3，页面切换是 SPA 式的，很顺滑</li><li><strong>主题</strong>：在一个开源游戏风主题的基础上自己改的，蓝色为主，配色和图标都换过了</li><li><strong>看板娘</strong>：Live2D 模型 Shizuku，亮色模式穿常服，暗色模式换睡衣，视线会跟着鼠标走，点她会有反应</li><li><strong>点击特效</strong>：屏幕上点击会出现小图案（可以在右上角菜单开关）</li><li><strong>字体</strong>：霞鹜文楷 Screen，按 unicode 分包按需加载，不拖速度</li><li><strong>背景音乐</strong>：用 Python 的 wave 模块合成的 8-bit 小曲，原创无版权问题</li><li><strong>搜索</strong>：Minisearch 全站全文搜索</li><li><strong>评论</strong>：giscus，用 GitHub 账号登录就能发言</li><li><strong>部署</strong>：GitHub Pages，源码开源在仓库里</li></ul></div><h2 id="过程中踩的坑" tabindex="-1">过程中踩的坑 <a class="header-anchor" href="#过程中踩的坑" aria-label="Permalink to &quot;过程中踩的坑&quot;">​</a></h2><ol><li><strong>Live2D 模型自托管</strong>：网上教程基本都是甩一个 CDN 链接完事。为了不被第三方 CDN 连累，我把 pixi.js、Cubism2 核心和模型文件共 111 个文件全部放进了站点里，5MB 出头，换来的稳定性是值得的。</li><li><strong>base 路径问题</strong>：站点部署在 <code>/LQY/</code> 子路径下，所有绝对路径都要注意前缀。看板娘组件里漏写一个前缀，模型就直接 404。</li><li><strong>背景音乐</strong>：原本想找现成的无版权曲子，找了一圈都不合适，最后干脆自己用方波和三角波合成了一首。Python 的 <code>wave</code> 模块意外地好用。</li></ol><h2 id="以后想加的功能" tabindex="-1">以后想加的功能 <a class="header-anchor" href="#以后想加的功能" aria-label="Permalink to &quot;以后想加的功能&quot;">​</a></h2><ul><li>[ ] 文章阅读时间估计</li><li>[ ] 标签页的筛选优化</li><li>[ ] 相册页（存点自己拍的照片）</li></ul><hr><p>总之，欢迎来到第三代。</p><p>搬家这件事大概一时半会儿停不下来，不过下次再动手之前，我会先看看月考日程表的。</p>',18)])])}const g=e(r,[["render",a]]);export{u as __pageData,g as default};
